def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    shift = shift % n
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

def max_fill(grid, capacity):
    total_units = sum(sum(row) for row in grid)
    from math import ceil
    return ceil(total_units / capacity)

def anti_shuffle(s):
    result = []
    word = []
    for ch in s:
        if ch == ' ':
            if word:
                result.append(''.join(sorted(word)))
                word = []
            result.append(' ')
        else:
            word.append(ch)
    if word:
        result.append(''.join(sorted(word)))
    return ''.join(result)

def prime_length(string):
    n = len(string)
    if n < 2:
        return 0
    return int(
        n in (2, 3, 5, 7) or
        (n % 2 != 0 and n % 3 != 0 and n % 5 != 0 and n % 7 != 0)
    )

def total_match(lst1, lst2):
    if sum(len(s) for s in lst1) <= sum(len(s) for s in lst2):
        return lst1
    else:
        return lst2
